from datetime import datetime
import math

class ParkingMeter:
    def __init__(self, hourly_rate: float = 4.0) -> None:
        self.hourly_rate = hourly_rate

    def fee(self, entry: datetime, exit: datetime) -> float:
        if exit < entry:
            raise ValueError("Exit time cannot be earlier than entry time")

        # Calculate duration in minutes
        total_minutes = (exit - entry).total_seconds() / 60.0

        # Flat penalty for stays longer than 24 hours (1440 minutes)
        if total_minutes > 1440:
            return 200.00

        # Free for stays of at most 15 minutes
        if total_minutes <= 15:
            return 0.0

        # Charge for every started hour (ceiling division)
        hours_charged = math.ceil(total_minutes / 60)

        # Calculate fee and round to two decimal places
        return round(hours_charged * self.hourly_rate, 2)
